import{_ as t,o as i,c as a,a5 as l}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"代码自动生成的注意事项","description":"","frontmatter":{"date":"2019-05-14T11:06:14","title":"代码自动生成的注意事项","categories":["Spring Boot","Jfinal"],"tags":["Spring Boot","Jfinal"]},"headers":[{"level":2,"title":"概要","slug":"概要","link":"#概要","children":[]},{"level":2,"title":"记一次排查过程","slug":"记一次排查过程","link":"#记一次排查过程","children":[]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]}],"relativePath":"posts/spring/springboot-4.md","filePath":"posts/spring/springboot-4.md"}'),o={name:"posts/spring/springboot-4.md"};function r(n,e,s,p,d,c){return i(),a("div",null,[...e[0]||(e[0]=[l('<h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>在“SpringBoot与Jfinal合体”中说到，使用代码生成技术，大大简化了编码量。但在爽的时候也要时刻注意，自动生成的代码是可能存在问题的，排查问题时不要忽略。</p><h2 id="记一次排查过程" tabindex="-1">记一次排查过程 <a class="header-anchor" href="#记一次排查过程" aria-label="Permalink to &quot;记一次排查过程&quot;">​</a></h2><p>在整合好了自动代码生成基础框架后，交给同事处理，具体业务需求。一开始一切正常，后面新增加了表，自动生成后，测试对应接口也是正常。</p><p>中间因为有其他任务安排，这部分任务先停了一段时间，这两天回来重新实现业务时，发现接口调用不了，提示空指针。</p><p>在排除了Maven依赖等问题之后，基本能判断是ActiveRecordPlugin的配置没有读到引起的，但查看ActivePlugin的注入的代码（包括SQL文件）都是正常的。</p><p>感觉有点无解的时候，想到要不重新生成试试，因为主要是Model的问题，于是重新生成了Model。之后运行代码，一切正常了。 重新核对，发现是<code>_MappingKit</code>，是表和类的映射关系只有一张表。</p><p>最后确认，当时看只要增加一张表，于是把之前的表屏蔽了，同时因为测试了新的接口是正常的，也就没有注意到生成的映射关系有问题。 而我自己呢因为是自动生成的代码没有注意排查。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>代码自动生成有好的一面，也有不足的一面（代码覆盖问题），而一个架构好用就在于能使用少犯错。在架构没有起来之前也就是靠人治，如规范，培训及惩罚等。</p><ol><li>代码自动生成，最好使用在新项目中。</li><li>代码自动生成，应该区分可变不可变内容，让覆盖更合理，让编码更放心。</li><li>代码自动生成，代码可能被覆盖或修改，排查问题时不要忽略。</li><li>修改代码生成器配置时，一定在注意影响范围并测试。</li></ol>',11)])])}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
